/* AUTO-GENERATED by scripts/gen-iot-examples.mjs — do not edit.
   Source of truth: iot-examples.manifest.json → the real composition files under apps/web/src/examples/iot/ */
export const iotExampleSource: Record<string, string> = {
  "device-fleet": "export function DeviceFleetExample() {\n  // Worst first. The ordering comes from KINETIX_DEVICE_STATUSES via compareDeviceAttention, so the\n  // list and the badges agree about which state is worse instead of holding two opinions.\n  const devices = [...DEMO_DEVICES].sort(compareDeviceAttention);\n\n  return (\n    <section className=\"flex flex-col gap-4\">\n      <header className=\"flex flex-wrap items-baseline justify-between gap-3\">\n        <h3 className=\"text-title-sm text-foreground\">Cold chain · Site 4</h3>\n        <DeviceStateSummary devices={devices} />\n      </header>\n\n      <div className=\"grid grid-cols-[repeat(auto-fill,minmax(min(100%,17rem),1fr))] gap-3\">\n        {devices.map((device) => (\n          <DeviceCard\n            key={device.id}\n            device={device}\n            reading={DEMO_READINGS[device.id]}\n            now={DEMO_NOW}\n          />\n        ))}\n      </div>\n    </section>\n  );\n}",
  "device-detail": "export function DeviceDetailExample() {\n  const device = deviceById(\"probe-a\");\n  const commands = DEMO_COMMANDS.filter((command) => command.deviceId === device.id);\n\n  return (\n    <article className=\"grid gap-4 lg:grid-cols-[minmax(0,1fr)_18rem]\">\n      <div className=\"flex flex-col gap-4\">\n        <TelemetryCard series={DEMO_SERIES.temperature} metric=\"Temperature\" precision={1} trendHeight={96} now={DEMO_NOW} />\n        <TelemetryCard series={DEMO_SERIES.humidity} metric=\"Humidity\" now={DEMO_NOW} />\n      </div>\n\n      <aside className=\"flex flex-col gap-5 rounded-xl border border-border bg-card p-4\">\n        <section className=\"flex flex-col gap-2\">\n          <h4 className=\"text-label-sm uppercase tracking-[0.12em] text-muted-foreground\">Connection</h4>\n          {/* A ten-minute freshness threshold is this device's reporting cadence, not a default the\n              library picked: a probe that reports twice a day is not unhealthy at hour three. */}\n          <ConnectionHealth device={device} freshnessMs={10 * 60_000} now={DEMO_NOW} />\n        </section>\n\n        <section className=\"flex flex-col gap-2\">\n          <h4 className=\"text-label-sm uppercase tracking-[0.12em] text-muted-foreground\">Firmware</h4>\n          <FirmwareStatus firmware={{ status: \"up-to-date\", currentVersion: device.firmwareVersion }} />\n        </section>\n\n        <section className=\"flex flex-col gap-3\">\n          <h4 className=\"text-label-sm uppercase tracking-[0.12em] text-muted-foreground\">Recent commands</h4>\n          {commands.length === 0 ? (\n            <p className=\"text-label-sm text-muted-foreground\">Nothing sent to this device.</p>\n          ) : (\n            commands.map((command) => <CommandStatus key={command.id} command={command} showName now={DEMO_NOW} />)\n          )}\n        </section>\n      </aside>\n    </article>\n  );\n}",
  "telemetry-board": "export function TelemetryBoardExample() {\n  return (\n    <div className=\"flex flex-col gap-4\">\n      <div className=\"grid grid-cols-[repeat(auto-fit,minmax(min(100%,15rem),1fr))] gap-3\">\n        <TelemetryCard series={DEMO_SERIES.temperature} metric=\"Temperature\" precision={1} now={DEMO_NOW} />\n        <TelemetryCard series={DEMO_SERIES.humidity} metric=\"Humidity\" now={DEMO_NOW} />\n        <TelemetryCard series={DEMO_SERIES.load} metric=\"Load\" precision={1} now={DEMO_NOW} />\n        {/* This sensor stopped answering four hours ago. The card shows that rather than a last-known\n            value dressed up as current, and its plot stops where the readings stopped. */}\n        <TelemetryCard series={DEMO_SERIES.airQuality} metric=\"PM2.5\" now={DEMO_NOW} />\n      </div>\n\n      {/* The trend on its own, at the size a detail view would give it. The two dropouts in the load\n          series are breaks in the line and a count in the footer — never interpolated across. */}\n      <figure className=\"flex flex-col gap-2 rounded-xl border border-border bg-card p-4\">\n        <figcaption className=\"text-label-sm uppercase tracking-[0.12em] text-muted-foreground\">\n          Load · last 3 hours\n        </figcaption>\n        <TelemetryTrend series={DEMO_SERIES.load} precision={1} height={120} />\n      </figure>\n    </div>\n  );\n}",
  "connection-troubleshooting": "/**\n * Six devices that a single \"offline\" dot would describe identically, and the facts that tell them\n * apart. The library does not diagnose the cause — it has no transport and cannot know whether a\n * gateway died or a firewall changed — it separates the signals so a person can.\n */\nconst CASES: { device: KinetixDevice; what: string }[] = [\n  { device: deviceById(\"probe-a\"), what: \"Reporting on schedule. Nothing to do.\" },\n  { device: deviceById(\"probe-b\"), what: \"Reachable, but the data behind it is hours old — the case a status field alone gets wrong.\" },\n  { device: deviceById(\"air-1\"), what: \"Weak signal and a fault reported by the device itself.\" },\n  { device: deviceById(\"probe-c\"), what: \"Not heard from in days, and the battery was nearly flat when it was.\" },\n  { device: { ...deviceById(\"gateway-1\"), signal: undefined }, what: \"No signal figure reported. Not the same as a signal of zero.\" },\n  { device: deviceById(\"meter-1\"), what: \"Mid-update. Its last reading is not its current reading.\" },\n];\n\nexport function ConnectionTroubleshootingExample() {\n  return (\n    <div className=\"grid gap-3 md:grid-cols-2\">\n      {CASES.map(({ device, what }) => (\n        <div key={device.id} className=\"flex flex-col gap-3 rounded-xl border border-border bg-card p-4\">\n          <div className=\"flex items-start justify-between gap-3\">\n            <span className=\"text-label-md text-foreground\">{device.name}</span>\n            <DeviceStatusBadge status={device.status} />\n          </div>\n          <ConnectionHealth device={device} freshnessMs={10 * 60_000} now={DEMO_NOW} />\n          <p className=\"text-label-sm text-muted-foreground\">{what}</p>\n        </div>\n      ))}\n    </div>\n  );\n}",
  "alert-inbox": "export function AlertInboxExample() {\n  // Local demo state. Acknowledging here changes this component and nothing else — there is no\n  // request, no device, and no server. See the note on the page.\n  const [acknowledged, setAcknowledged] = React.useState<Record<string, string>>({});\n  const [showAcknowledged, setShowAcknowledged] = React.useState(false);\n\n  const alerts = DEMO_ALERTS.map((alert) =>\n    acknowledged[alert.id] ? { ...alert, acknowledgedAt: acknowledged[alert.id] } : alert,\n  );\n\n  // `activeAlerts` sorts newest first and, by default, leaves acknowledged ones out — so \"show\n  // acknowledged\" is a flag it already takes rather than a second code path here.\n  const visible = activeAlerts(alerts, { includeAcknowledged: showAcknowledged });\n  const loudest = highestAlertSeverity(alerts);\n\n  return (\n    <section className=\"flex flex-col gap-3\">\n      <header className=\"flex flex-wrap items-center justify-between gap-3\">\n        <p className=\"text-label-md text-foreground\">\n          {visible.length} alert{visible.length === 1 ? \"\" : \"s\"}\n          {loudest ? <span className=\"text-muted-foreground\"> · loudest is {loudest}</span> : null}\n        </p>\n        <label className=\"flex min-h-6 cursor-pointer items-center gap-2 py-1 text-label-sm text-muted-foreground\">\n          <input\n            type=\"checkbox\"\n            checked={showAcknowledged}\n            onChange={(event) => setShowAcknowledged(event.target.checked)}\n            className=\"size-4 rounded border-input\"\n          />\n          Show acknowledged\n        </label>\n      </header>\n\n      {visible.length === 0 ? (\n        <p className=\"rounded-lg border border-dashed border-border p-6 text-center text-label-md text-muted-foreground\">\n          Nothing unacknowledged.\n        </p>\n      ) : (\n        <ul className=\"flex flex-col gap-2\">\n          {visible.map((alert) => (\n            <li key={alert.id}>\n              <AlertCard\n                alert={alert}\n                deviceName={deviceById(alert.deviceId).name}\n                now={DEMO_NOW}\n                action={\n                  alert.acknowledgedAt ? null : (\n                    <button\n                      type=\"button\"\n                      onClick={() => setAcknowledged((prev) => ({ ...prev, [alert.id]: DEMO_NOW }))}\n                      className=\"rounded-md border border-input px-2 py-1 text-label-sm text-foreground hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring\"\n                    >\n                      {/* Named, not an icon: \"Acknowledge\" beside a device name is what a screen\n                          reader announces, and a bare tick is not. */}\n                      <span className=\"sr-only\">Acknowledge alert: {alert.message}. </span>\n                      Acknowledge\n                    </button>\n                  )\n                }\n              />\n            </li>\n          ))}\n        </ul>\n      )}\n    </section>\n  );\n}",
  "device-dashboard": "/**\n * Everything below is LOCAL DEMO STATE.\n *\n * Toggling a device, moving a slider or acknowledging an alert changes a `useState` value in this\n * component and nothing else. `@kinetixui/iot` has no transport — no MQTT, no BLE, no WebSocket, no\n * HTTP client — so nothing here reaches a device, and a showcase that implied otherwise would be\n * advertising a capability the package does not have.\n */\nconst GROUPS = [\"All\", \"Cold store A\", \"Plant room\", \"Bay 2\"] as const;\ntype Group = (typeof GROUPS)[number];\n\n// The product supplies these. `@kinetixui/iot` hard-codes no mode vocabulary, because the same\n// control serves a chiller, an irrigation valve and a conveyor.\nconst MODES = [\n  { id: \"cool\", label: \"Cool\" },\n  { id: \"hold\", label: \"Hold\" },\n  { id: \"defrost\", label: \"Defrost\", description: \"Unavailable until the cycle completes\", unavailable: true },\n];\n\nexport function DeviceDashboardExample() {\n  const [group, setGroup] = React.useState<Group>(\"All\");\n  const [selectedId, setSelectedId] = React.useState<string>(\"probe-a\");\n  const [overrides, setOverrides] = React.useState<Record<string, KinetixDeviceStatus>>({});\n  const [acknowledged, setAcknowledged] = React.useState<Record<string, string>>({});\n  // Confirmed values — what the imaginary device has reported.\n  const [powered, setPowered] = React.useState<\"on\" | \"off\">(\"on\");\n  const [intensity, setIntensity] = React.useState(62);\n  const [target, setTarget] = React.useState(4);\n  const [mode, setMode] = React.useState(\"cool\");\n\n  // Requested values — what the user has asked for and the device has not confirmed yet.\n  const [pending, setPending] = React.useState<null | { kind: \"power\" | \"level\" | \"target\" | \"mode\"; value: string | number }>(null);\n\n  // A command that resolves after a beat, so the requested-versus-confirmed gap is visible rather\n  // than theoretical. A product would replace this with whatever its transport reports back.\n  React.useEffect(() => {\n    if (!pending) return;\n    const timer = setTimeout(() => {\n      if (pending.kind === \"power\") setPowered(pending.value as \"on\" | \"off\");\n      if (pending.kind === \"level\") setIntensity(pending.value as number);\n      if (pending.kind === \"target\") setTarget(pending.value as number);\n      if (pending.kind === \"mode\") setMode(pending.value as string);\n      setPending(null);\n    }, 1100);\n    return () => clearTimeout(timer);\n  }, [pending]);\n\n  const request = (kind: \"power\" | \"level\" | \"target\" | \"mode\", value: string | number) => setPending({ kind, value });\n\n  const devices: KinetixDevice[] = DEMO_DEVICES.map((device) =>\n    overrides[device.id] ? { ...device, status: overrides[device.id]! } : device,\n  );\n  const inGroup = group === \"All\" ? devices : devices.filter((device) => device.locationName === group);\n  const ordered = [...inGroup].sort(compareDeviceAttention);\n  const summary = summarizeDevices(inGroup);\n  const selected = deviceById(selectedId);\n\n  // One resolution for all four controls, so they cannot disagree about whether the device is\n  // reachable or a command is outstanding.\n  const control = resolveControlState({\n    deviceStatus: selected.status,\n    commandStatus: pending ? \"sent\" : undefined,\n  });\n  const alerts = DEMO_ALERTS.map((a) => (acknowledged[a.id] ? { ...a, acknowledgedAt: acknowledged[a.id] } : a));\n  const openAlerts = alerts.filter((a) => !a.acknowledgedAt);\n\n  return (\n    <div className=\"flex flex-col gap-4\">\n      {/* ---------------------------------------------------------------- header */}\n      <header className=\"flex flex-col gap-3 rounded-xl border border-border bg-card p-4\">\n        <div className=\"flex flex-wrap items-baseline justify-between gap-x-4 gap-y-2\">\n          <h3 className=\"text-title-sm text-foreground\">Cold chain · Site 4</h3>\n          {/* A count, not a verdict. Whether two offline devices is fine depends on what they are. */}\n          <p className=\"text-label-sm text-muted-foreground\">\n            {summary.total} device{summary.total === 1 ? \"\" : \"s\"} · {summary.needsAttention} needing attention ·{\" \"}\n            {openAlerts.length} open alert{openAlerts.length === 1 ? \"\" : \"s\"}\n          </p>\n        </div>\n\n        {/* The group selector every product surveyed puts here, generalised from \"rooms\". */}\n        <div role=\"tablist\" aria-label=\"Device group\" className=\"-mx-1 flex gap-1 overflow-x-auto px-1 pb-1\">\n          {GROUPS.map((name) => (\n            <button\n              key={name}\n              role=\"tab\"\n              type=\"button\"\n              aria-selected={group === name}\n              onClick={() => setGroup(name)}\n              className={[\n                \"shrink-0 rounded-full px-3 py-1.5 text-label-sm transition-colors duration-200 motion-reduce:transition-none\",\n                \"focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring\",\n                group === name ? \"bg-foreground text-background\" : \"border border-input text-muted-foreground hover:text-foreground\",\n              ].join(\" \")}\n            >\n              {name}\n            </button>\n          ))}\n        </div>\n\n        <DeviceStateSummary devices={inGroup} />\n      </header>\n\n      {/* ---------------------------------------------------------------- fleet + detail */}\n      <div className=\"grid gap-4 xl:grid-cols-[minmax(0,1fr)_20rem]\">\n        <section aria-label=\"Devices\" className=\"grid grid-cols-[repeat(auto-fill,minmax(min(100%,16rem),1fr))] gap-3\">\n          {ordered.map((device) => {\n            const isSelected = device.id === selectedId;\n            return (\n              <DeviceCard\n                key={device.id}\n                device={device}\n                reading={DEMO_READINGS[device.id]}\n                now={DEMO_NOW}\n                className={isSelected ? \"border-foreground/40 ring-1 ring-foreground/20\" : \"\"}\n                action={\n                  <button\n                    type=\"button\"\n                    onClick={() => setSelectedId(device.id)}\n                    aria-pressed={isSelected}\n                    className=\"rounded-md border border-input px-2 py-1 text-label-sm text-foreground hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring\"\n                  >\n                    <span className=\"sr-only\">Show details for {device.name}. </span>\n                    Details\n                  </button>\n                }\n              />\n            );\n          })}\n          {ordered.length === 0 ? (\n            <p className=\"rounded-xl border border-dashed border-border p-6 text-label-md text-muted-foreground\">\n              No devices in this group.\n            </p>\n          ) : null}\n        </section>\n\n        {/* The detail panel: the tile-to-detail pattern, as a column beside the grid on wide screens\n            and a section below it on narrow ones. */}\n        <aside aria-label={`Detail: ${selected.name}`} className=\"flex flex-col gap-4 rounded-xl border border-border bg-card p-4\">\n          <div className=\"flex flex-col gap-1\">\n            <span className=\"text-label-sm uppercase tracking-[0.12em] text-muted-foreground\">Selected device</span>\n            <span className=\"text-title-sm text-foreground\">{selected.name}</span>\n            <span className=\"text-label-sm text-muted-foreground\">{selected.locationName}</span>\n          </div>\n\n          {/* The control layer, wired to LOCAL DEMO STATE.\n              A request is held for 1.1s before it \"confirms\", because that is what a device on a\n              real network does — and because the state worth showing is the one in between. Nothing\n              here reaches a device: `@kinetixui/iot` has no transport of any kind. */}\n          <fieldset className=\"flex flex-col gap-4 border-t border-border pt-4\">\n            <legend className=\"sr-only\">Demonstration controls for {selected.name}</legend>\n\n            <DevicePowerControl\n              state={powered}\n              requested={pending?.kind === \"power\" ? (pending.value as \"on\" | \"off\") : undefined}\n              control={control}\n              label={`${selected.name} power`}\n              onToggle={(next) => request(\"power\", next)}\n            />\n\n            <DeviceLevelControl\n              value={intensity}\n              target={pending?.kind === \"level\" ? (pending.value as number) : undefined}\n              control={control}\n              label=\"Intensity\"\n              unit=\"%\"\n              onCommit={(next) => request(\"level\", next)}\n            />\n\n            <DeviceSetpointControl\n              current={selected.id === \"probe-a\" ? 4.2 : undefined}\n              target={target}\n              requestedTarget={pending?.kind === \"target\" ? (pending.value as number) : undefined}\n              min={-20}\n              max={25}\n              unit=\"°C\"\n              label=\"Target temperature\"\n              control={control}\n              onCommit={(next) => request(\"target\", next)}\n            />\n\n            <DeviceModeControl\n              modes={MODES}\n              value={mode}\n              requested={pending?.kind === \"mode\" ? (pending.value as string) : undefined}\n              control={control}\n              label=\"Operating mode\"\n              onSelect={(id) => request(\"mode\", id)}\n            />\n\n            <div className=\"flex flex-col gap-1.5\">\n              <span className=\"text-label-md text-foreground\">Simulate a state</span>\n              <div className=\"flex flex-wrap gap-1.5\">\n                {([\"online\", \"syncing\", \"stale\", \"offline\", \"error\"] as const).map((status) => (\n                  <button\n                    key={status}\n                    type=\"button\"\n                    onClick={() => setOverrides((prev) => ({ ...prev, [selected.id]: status }))}\n                    className=\"rounded-full border border-input px-2.5 py-1 text-label-sm text-muted-foreground transition-colors duration-200 hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring motion-reduce:transition-none\"\n                  >\n                    {describeDeviceStatus(status)}\n                  </button>\n                ))}\n              </div>\n              {/* One polite live region for the whole panel, announced only when the reader acted.\n                  Telemetry updates are deliberately NOT announced — a dashboard that narrates every\n                  reading is a dashboard nobody can use with a screen reader. */}\n              <p aria-live=\"polite\" className=\"text-label-sm text-muted-foreground\">\n                {overrides[selected.id] ? `${selected.name} is now ${describeDeviceStatus(overrides[selected.id]!).toLowerCase()}.` : \"\"}\n              </p>\n            </div>\n          </fieldset>\n        </aside>\n      </div>\n\n      {/* ---------------------------------------------------------------- telemetry */}\n      <section aria-label=\"Telemetry\" className=\"grid grid-cols-[repeat(auto-fit,minmax(min(100%,14rem),1fr))] gap-3\">\n        <TelemetryCard series={DEMO_SERIES.temperature} metric=\"Temperature\" precision={1} now={DEMO_NOW} />\n        <TelemetryCard series={DEMO_SERIES.humidity} metric=\"Humidity\" now={DEMO_NOW} />\n        <TelemetryCard series={DEMO_SERIES.load} metric=\"Load\" precision={1} now={DEMO_NOW} />\n        <TelemetryCard series={DEMO_SERIES.airQuality} metric=\"PM2.5\" now={DEMO_NOW} />\n      </section>\n\n      {/* ---------------------------------------------------------------- alerts + activity */}\n      <div className=\"grid gap-4 lg:grid-cols-2\">\n        <section aria-label=\"Alerts\" className=\"flex flex-col gap-2\">\n          <h4 className=\"text-label-sm uppercase tracking-[0.12em] text-muted-foreground\">Alerts</h4>\n          {openAlerts.length === 0 ? (\n            <p className=\"rounded-lg border border-dashed border-border p-4 text-label-md text-muted-foreground\">\n              Nothing unacknowledged.\n            </p>\n          ) : (\n            <ul className=\"flex flex-col gap-2\">\n              {openAlerts.map((alert) => (\n                <li key={alert.id}>\n                  <AlertCard\n                    alert={alert}\n                    deviceName={deviceById(alert.deviceId).name}\n                    now={DEMO_NOW}\n                    action={\n                      <button\n                        type=\"button\"\n                        onClick={() => setAcknowledged((prev) => ({ ...prev, [alert.id]: DEMO_NOW }))}\n                        className=\"rounded-md border border-input px-2 py-1 text-label-sm text-foreground hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring\"\n                      >\n                        <span className=\"sr-only\">Acknowledge alert: {alert.message}. </span>\n                        Acknowledge\n                      </button>\n                    }\n                  />\n                </li>\n              ))}\n            </ul>\n          )}\n        </section>\n\n        <section aria-label=\"Activity\" className=\"flex flex-col gap-2\">\n          <h4 className=\"text-label-sm uppercase tracking-[0.12em] text-muted-foreground\">Recent commands</h4>\n          {/* The time-rail activity list: the timestamp gutter is the structure, not a trailing note. */}\n          <ul className=\"flex flex-col\">\n            {DEMO_COMMANDS.map((command) => (\n              <li key={command.id} className=\"grid grid-cols-[auto_1fr] gap-3 border-s border-border ps-4 pb-4 last:pb-0\">\n                <span aria-hidden=\"true\" className=\"-ms-[1.3rem] mt-1.5 size-2 rounded-full bg-border\" />\n                <span className=\"flex flex-col gap-0.5\">\n                  <span className=\"text-label-md text-foreground\">{deviceById(command.deviceId).name}</span>\n                  <CommandStatus command={command} showName now={DEMO_NOW} />\n                </span>\n              </li>\n            ))}\n          </ul>\n        </section>\n      </div>\n    </div>\n  );\n}",
  "connected-space": "/**\n * A connected space: zones, the devices in one of them, and the automations that run it.\n *\n * Everything below is LOCAL DEMO STATE, and every device, zone and routine here is invented.\n * Toggling something changes a `useState` value in this component. `@kinetixui/iot` has no transport\n * — no MQTT, no BLE, no Matter, no WebSocket — so nothing reaches a device, and a showcase implying\n * otherwise would be advertising a capability the package does not have.\n *\n * The one behaviour worth watching: a command is held for 1.1s before it confirms. During that\n * window the control shows what you **asked for** as clearly distinct from what the device has\n * **reported**, which is the gap most device UIs paper over with an optimistic update.\n */\nconst NOW = \"2026-01-01T12:00:00.000Z\";\nconst ago = (ms: number) => new Date(Date.parse(NOW) - ms).toISOString();\nconst ahead = (ms: number) => new Date(Date.parse(NOW) + ms).toISOString();\n\nconst ZONES = [\n  { id: \"hall\", name: \"Packing hall\", kind: \"Zone\", deviceCount: 12, activeCount: 7, category: \"light\" as const, summary: \"21°C · 48% RH\" },\n  { id: \"field\", name: \"North field\", kind: \"Zone\", deviceCount: 8, activeCount: 4, attentionCount: 1, category: \"pump\" as const, summary: \"3 of 8 valves open\" },\n  { id: \"store\", name: \"Cold store\", kind: \"Site\", deviceCount: 5, activeCount: 0, category: \"sensor\" as const, summary: \"All within range\" },\n];\n\nconst FIXTURES: KinetixDevice[] = [\n  { id: \"bench\", name: \"Bench lamps\", type: \"light\", status: \"online\", lastSeenAt: ago(30_000), locationName: \"Packing hall\" },\n  { id: \"bay\", name: \"Loading bay flood\", type: \"light\", status: \"online\", lastSeenAt: ago(90_000), locationName: \"Packing hall\" },\n  { id: \"yard\", name: \"Yard flood\", type: \"light\", status: \"offline\", lastSeenAt: ago(3 * 3_600_000), locationName: \"Packing hall\" },\n];\n\nconst ROUTINES: KinetixAutomation[] = [\n  {\n    id: \"shutdown\",\n    name: \"End of shift\",\n    kind: \"scene\",\n    status: \"idle\",\n    enabled: true,\n    actions: \"9 lights off, 2 doors locked\",\n    lastRunAt: ago(14 * 3_600_000),\n  },\n  {\n    id: \"irrigation\",\n    name: \"Evening irrigation\",\n    kind: \"schedule\",\n    status: \"idle\",\n    enabled: true,\n    trigger: \"Weekdays 18:30\",\n    actions: \"2 valves, 40 min\",\n    lastRunAt: ago(20 * 3_600_000),\n    nextRunAt: ahead(6 * 3_600_000),\n  },\n  {\n    id: \"frost\",\n    name: \"Frost protection\",\n    kind: \"routine\",\n    status: \"failed\",\n    enabled: true,\n    trigger: \"Outside below 2°C\",\n    actions: \"Circulation pump\",\n    lastRunAt: ago(90 * 60_000),\n    errorMessage: \"Pump did not acknowledge\",\n  },\n];\n\ntype Pending = { id: string; kind: \"power\" | \"level\"; value: string | number };\n\nexport function ConnectedSpaceExample() {\n  const [zoneId, setZoneId] = React.useState(\"hall\");\n  const [power, setPower] = React.useState<Record<string, \"on\" | \"off\">>({ bench: \"on\", bay: \"off\", yard: \"on\" });\n  const [level, setLevel] = React.useState<Record<string, number>>({ bench: 100, bay: 40, yard: 70 });\n  const [pending, setPending] = React.useState<Pending | null>(null);\n  const [routines, setRoutines] = React.useState(ROUTINES);\n  const [openId, setOpenId] = React.useState<string | null>(\"bench\");\n\n  React.useEffect(() => {\n    if (!pending) return;\n    const timer = setTimeout(() => {\n      if (pending.kind === \"power\") setPower((p) => ({ ...p, [pending.id]: pending.value as \"on\" | \"off\" }));\n      if (pending.kind === \"level\") setLevel((l) => ({ ...l, [pending.id]: pending.value as number }));\n      setPending(null);\n    }, 1100);\n    return () => clearTimeout(timer);\n  }, [pending]);\n\n  const controlFor = (device: KinetixDevice) =>\n    resolveControlState({\n      deviceStatus: device.status,\n      commandStatus: pending?.id === device.id ? \"sent\" : undefined,\n    });\n\n  const zone = ZONES.find((z) => z.id === zoneId) ?? ZONES[0]!;\n\n  return (\n    <section aria-label=\"Connected space\" className=\"flex flex-col gap-6\">\n      {/* ------------------------------------------------------------------ zones */}\n      <div>\n        <h3 className=\"mb-3 text-label-sm uppercase tracking-[0.12em] text-muted-foreground\">Zones</h3>\n        <div className=\"grid grid-cols-[repeat(auto-fit,minmax(min(100%,15rem),1fr))] gap-3\">\n          {ZONES.map((z) => (\n            <DeviceGroupCard\n              key={z.id}\n              name={z.name}\n              kind={z.kind}\n              deviceCount={z.deviceCount}\n              activeCount={z.activeCount}\n              attentionCount={z.attentionCount}\n              category={z.category}\n              summary={z.summary}\n              onSelect={() => setZoneId(z.id)}\n              className={z.id === zoneId ? \"ring-2 ring-ring ring-offset-2 ring-offset-background\" : undefined}\n            />\n          ))}\n        </div>\n      </div>\n\n      {/* ------------------------------------------------------------- the devices */}\n      <div>\n        <h3 className=\"mb-3 text-label-sm uppercase tracking-[0.12em] text-muted-foreground\">{zone.name} — fixtures</h3>\n        <div className=\"grid grid-cols-[repeat(auto-fit,minmax(min(100%,16rem),1fr))] gap-3\">\n          {FIXTURES.map((device) => {\n            const control = controlFor(device);\n            const requestedPower = pending?.id === device.id && pending.kind === \"power\" ? (pending.value as \"on\" | \"off\") : undefined;\n            const on = power[device.id] === \"on\";\n\n            return (\n              <DeviceControlCard\n                key={device.id}\n                device={device}\n                active={on && device.status === \"online\"}\n                control={control}\n                open={openId === device.id}\n                onOpenChange={(next) => setOpenId(next ? device.id : null)}\n                statusLine={\n                  device.status === \"offline\"\n                    ? \"Last reachable 3h ago\"\n                    : requestedPower\n                      ? `Turning ${requestedPower}`\n                      : on\n                        ? `${level[device.id]}% brightness`\n                        : \"Off\"\n                }\n                primaryControl={\n                  <DevicePowerControl\n                    state={power[device.id]}\n                    requested={requestedPower}\n                    control={control}\n                    label={`${device.name} power`}\n                    showLabel={false}\n                    onToggle={(next) => setPending({ id: device.id, kind: \"power\", value: next })}\n                  />\n                }\n                expanded={\n                  <DeviceLevelControl\n                    value={level[device.id]}\n                    target={pending?.id === device.id && pending.kind === \"level\" ? (pending.value as number) : undefined}\n                    control={control}\n                    label={`${device.name} brightness`}\n                    unit=\"%\"\n                    onCommit={(next) => setPending({ id: device.id, kind: \"level\", value: next })}\n                  />\n                }\n              />\n            );\n          })}\n        </div>\n      </div>\n\n      {/* ---------------------------------------------------------------- routines */}\n      <div>\n        <h3 className=\"mb-3 text-label-sm uppercase tracking-[0.12em] text-muted-foreground\">Automations</h3>\n        <div className=\"grid grid-cols-[repeat(auto-fit,minmax(min(100%,17rem),1fr))] gap-3\">\n          {routines.map((automation) => (\n            <RoutineCard\n              key={automation.id}\n              automation={automation}\n              now={NOW}\n              onToggleEnabled={(next) =>\n                setRoutines((rs) => rs.map((r) => (r.id === automation.id ? { ...r, enabled: next } : r)))\n              }\n              onRun={() => {\n                // A run that finishes on its own, so \"running\" is a state you can actually watch.\n                setRoutines((rs) => rs.map((r) => (r.id === automation.id ? { ...r, status: \"running\" } : r)));\n                setTimeout(\n                  () =>\n                    setRoutines((rs) =>\n                      rs.map((r) => (r.id === automation.id ? { ...r, status: \"idle\", lastRunAt: NOW } : r)),\n                    ),\n                  1800,\n                );\n              }}\n            />\n          ))}\n        </div>\n      </div>\n    </section>\n  );\n}"
};
